/** @type {import('next').NextConfig} */

const nextConfig = {
    trailingSlash: true,
    reactStrictMode: false,
    turbopack: {
        rules: {
            '*.svg': {
                loaders: ['@svgr/webpack'],
                as: '*.js',
            },
        },
    },
    webpack: (config) => {
        config.module.rules.push({
            test: /\.svg$/i,
            issuer: /\.[jt]sx?$/,
            use: ['@svgr/webpack'],
        });
        return config;
    },
    images: {
        remotePatterns: [
            {
                hostname: 'firebasestorage.googleapis.com',
            },
            {
                protocol: 'http',
                hostname: '**',
                port: '9199',
                pathname: '**',
            },
        ],
    },
};

export default nextConfig;

