import { FirebaseAuthProvider } from '@modules/firebase/components';
import { Instrument_Sans } from 'next/font/google';
import { ReactNode } from 'react';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { JotaiProvider } from './_components/JotaiProvider';
import './globals.css';

const instrumentSans = Instrument_Sans({
  subsets: ['latin'],
  display: 'swap',
  variable: '--font-instrumentsans',
  adjustFontFallback: false,
});

export default async function RootLayout({
  children,
}: {
  children: ReactNode;
}) {
  return (
    <html lang="en" className={`${instrumentSans.variable} font-sans`}>
      <body className="m-auto">
        <JotaiProvider>
          <FirebaseAuthProvider>{children}</FirebaseAuthProvider>
        </JotaiProvider>
        <ToastContainer
          position="bottom-left"
          autoClose={3000}
          hideProgressBar={false}
          closeOnClick={true}
          pauseOnHover={true}
          draggable={true}
          pauseOnFocusLoss={true}
          rtl={false}
        />
      </body>
    </html>
  );
}

